﻿<style>
.print-format { font-family: Lato, Arial, sans-serif; color: #102136; font-size: 11pt; padding: 20mm; }
.dd-brand { color: #102136 !important; font-size: 30pt; font-weight: 700; margin: 0 0 8mm; border-bottom: 1px solid #00877f; padding-bottom: 4mm; }
.dd-brand span { color: #00877f; }
.dd-caption { color: #64748b; font-size: 9pt; text-transform: uppercase; letter-spacing: .6px; }
.dd-reference { font-size: 16pt; font-weight: 700; }
.dd-panel { background: #eef8f7; padding: 6mm; margin: 8mm 0; border-radius: 2mm; }
.dd-panel table { width: 100%; }
.dd-panel td { width: 50%; vertical-align: top; }
.dd-panel td + td { border-left: 1px solid #dce4e8; padding-left: 6mm; }
.dd-heading { font-size: 20pt; font-weight: 700; margin: 8mm 0 3mm; }
.dd-items { width: 100%; border-collapse: collapse; }
.dd-items th { color: #64748b; font-size: 9pt; padding: 3mm 2mm; border-bottom: 1px solid #00877f; }
.dd-items td { padding: 5mm 2mm; border-bottom: 1px solid #dce4e8; vertical-align: top; }
.dd-items tr { page-break-inside: avoid; }
.dd-number { color: #00877f; font-weight: 700; }
.dd-money { text-align: right; white-space: nowrap; }
.dd-total { text-align: right; font-size: 16pt; font-weight: 700; color: #00877f; margin: 6mm 0; }
.dd-notes { white-space: pre-wrap; }
</style>
<div class="dd-brand">Diaspora <span>Desk</span></div>
<table style="width:100%"><tr><td><div class="dd-caption">Quotation reference</div><div class="dd-reference">{{ doc.name | e }}</div></td><td style="text-align:right"><div class="dd-caption">Request reference</div><strong>{{ doc.request | e }}</strong><br>{{ doc.status | e }}</td></tr></table>
<div class="dd-panel"><table><tr><td><div class="dd-caption">Prepared for</div><strong>{{ doc.customer_name | e }}</strong><br>{{ doc.customer_email | e }}</td><td><div class="dd-caption">Quotation date</div><strong>{{ frappe.utils.formatdate(doc.quotation_date) }}</strong><br><span class="dd-caption">Valid until</span><br>{{ frappe.utils.formatdate(doc.valid_until) }}</td></tr></table></div>
<h2 class="dd-heading">Your quotation</h2>
<p>Proposed scope and pricing for your requested project checks. Planned scout numbers form part of this quotation. Current assignments are shown separately in your customer account after your deposit is verified.</p>
<table class="dd-items"><thead><tr><th style="width:9%">Project</th><th>Scope</th><th class="dd-money">Scouts planned</th><th class="dd-money">Quantity</th><th class="dd-money">Rate ({{ doc.currency | e }})</th><th class="dd-money">Amount</th></tr></thead><tbody>
{% for item in doc.items %}{% set assignments = frappe.get_all("Field Task", filters={"field_request": item.field_request, "status": ["!=", "Cancelled"]}, fields=["scout_profile"]) %}<tr><td class="dd-number">{{ "%02d" | format(loop.index) }}</td><td><strong>{{ item.project_title | e }}</strong>{% if item.description != item.project_title %}<div class="dd-notes">{{ item.description | e }}</div>{% endif %}<div class="dd-caption">Currently assigned: {{ assignments | map(attribute="scout_profile") | unique | list | length }} scouts at time of printing</div></td><td class="dd-money">{{ item.get("planned_scouts") or "To confirm" }}</td><td class="dd-money">{{ item.quantity }}</td><td class="dd-money">{{ "{:,.2f}".format(item.rate) }}</td><td class="dd-money">{{ "{:,.2f}".format(item.amount) }}</td></tr>{% endfor %}
</tbody></table>
<div class="dd-total">Total {{ doc.currency | e }} {{ "{:,.2f}".format(doc.total) }}</div>
{% if doc.get("deposit_amount") %}<p><strong>50% deposit:</strong> {{ doc.currency | e }} {{ "{:,.2f}".format(doc.deposit_amount) }}<br><strong>50% balance on completion:</strong> {{ doc.currency | e }} {{ "{:,.2f}".format(doc.balance_amount) }}</p><p>Accept this quotation and pay the deposit through your customer account. Scouts are assigned after the deposit is verified. Both payments are linked to this quotation.</p>{% endif %}{% if doc.agreed_completion_date %}<div class="dd-panel"><div class="dd-caption">Proposed completion date</div><strong>{{ frappe.utils.formatdate(doc.agreed_completion_date) }}</strong></div>{% endif %}
{% if doc.terms %}<h3>Terms and payment arrangements</h3><div class="dd-notes">{{ doc.terms | e }}</div>{% endif %}

records.script:
name = frappe.form_dict.get("field_request")
request = frappe.get_doc("Field Request", name)
request.check_permission("write")
if request.alignment_review or not request.project_number or not request.county:
    frappe.throw("Confirm the project's scope and county before assigning scouts.")
if request.status in ["Completed", "Cancelled"]:
    frappe.throw("Cannot assign a completed or cancelled project.")
assignments = json.loads(frappe.form_dict.get("assignments") or "[]")
if not assignments or len(assignments) > 20:
    frappe.throw("Choose between one and twenty scout assignments.")
seen = []
created = []
for assignment in assignments:
    scout = assignment.get("scout")
    if not scout or scout in seen:
        frappe.throw("Choose each scout once.")
    seen.append(scout)
    profile = frappe.get_doc("Scout Profile", scout)
    profile.check_permission("read")
    responsibility = (assignment.get("responsibility") or "").strip()
    if len(assignments) > 1 and not responsibility:
        frappe.throw("Give each scout a responsibility when assigning multiple scouts.")
    existing = frappe.db.get_value("Field Task", {"field_request": name, "scout_profile": scout, "status": ["not in", ["Cancelled", "Approved"]]}, "name")
    if existing:
        created.append(existing)
    else:
        task = frappe.get_doc({"doctype": "Field Task", "field_request": name, "scout_profile": scout, "status": "Assigned", "assigned_at": frappe.utils.now(), "responsibility": responsibility, "location": assignment.get("location"), "questionnaire": assignment.get("questionnaire")})
        task.insert()
        created.append(task.name)
request = frappe.get_doc("Field Request", name)
if request.status == "Awaiting Assignment":
    request.status = "Assigned"
    request.save()
if request.diaspora_request:
    # Derived workflow status only; no direct customer-record edit permission.
    status = frappe.db.get_value("Diaspora Request", request.diaspora_request, "status")
    if status in ["New", "In Review"]:
        frappe.db.set_value("Diaspora Request", request.diaspora_request, "status", "Assigned")
frappe.response["message"] = {"tasks": created}

# Owner-approved currency amendment: USD 100 -> KES 13,000, 16 October 2026.
# Deliberately scoped and idempotent; never carries forward customer acceptance.
if frappe.request.method != "POST" or "System Manager" not in frappe.get_all("Has Role", filters={"parent": frappe.session.user, "parenttype": "User"}, pluck="role"):
    frappe.throw("Not permitted", frappe.PermissionError)
frappe.db.sql("SELECT name FROM `tabDiaspora Request` WHERE name=%s FOR UPDATE", ("DD-2026-00028",))
old = frappe.get_doc("DD Quotation", "DQ-2026-00162")
existing = frappe.db.get_value("DD Quotation", {"request": "DD-2026-00028", "terms": old.terms + "\nReplaces DQ-2026-00162: currency amendment approved at KES 13,000."}, "name")
if existing:
    frappe.response["message"] = {"quotation": existing, "already_created": True}
else:
    if old.request != "DD-2026-00028" or old.status != "Accepted" or old.currency != "USD" or float(old.total) != 100 or len(old.items) != 1 or float(old.items[0].quantity) != 1:
        frappe.throw("Quotation changed; review the amendment again")
    payments = frappe.get_all("DD Payment", filters={"quotation": old.name}, fields=["name", "status"])
    for payment in payments:
        if payment.status != "Unpaid" or frappe.db.exists("DD Payment Attempt", {"payment": payment.name}):
            frappe.throw("Payment activity exists; reconcile before amending")
    if frappe.db.exists("DD Quotation", {"request": old.request, "status": "Issued"}):
        frappe.throw("Another quotation is already issued")
    item = old.items[0]
    # Retain the original record, acceptance metadata and unpaid obligations.
    # Its Withdrawn status invalidates all checkout against those obligations.
    frappe.db.set_value("DD Quotation", old.name, "status", "Withdrawn")
    replacement = frappe.get_doc({"doctype": "DD Quotation", "request": old.request, "status": "Issued", "currency": "KES", "quotation_date": frappe.utils.today(), "valid_until": old.valid_until, "terms": old.terms + "\nReplaces DQ-2026-00162: currency amendment approved at KES 13,000.", "items": [{"field_request": item.field_request, "description": item.description, "quantity": 1, "rate": 13000, "planned_scouts": item.planned_scouts}]}).insert()
    frappe.response["message"] = {"quotation": replacement.name, "status": replacement.status, "currency": replacement.currency, "total": replacement.total, "deposit": replacement.deposit_amount, "balance": replacement.balance_amount}

# RestrictedPython-compatible helpers for the production script runtime.
def roles(user=None):
    return frappe.get_all("Has Role", filters={"parent": user or frappe.session.user, "parenttype": "User"}, pluck="role")

def zip(left, right):
    return [(left[index], right[index]) for index in range(min(len(left), len(right)))]

def money(value):
    text = str(value).strip()
    number = float(text)
    if number != number or number < 0 or number > 1000000000:
        frappe.throw("Invalid monetary amount")
    if "e" in text.lower():
        text = f"{number:.12f}"
    parts = text.lstrip("+-").split(".")
    fraction = parts[1] if len(parts) > 1 else ""
    cents = int(parts[0] or "0") * 100 + int((fraction + "00")[:2])
    if len(fraction) > 2 and fraction[2] >= "5":
        cents += 1
    return cents / 100.0

def instalments(total):
    cents = int(round(money(total) * 100))
    if cents < 2:
        frappe.throw("Quotation must allow two positive payments")
    first = (cents + 1) // 2
    return first / 100.0, (cents - first) / 100.0

def getdate(value=None):
    return frappe.utils.getdate(value) if value else frappe.utils.getdate()

def now_datetime():
    return frappe.utils.now_datetime()

def urlencode(values):
    parts = []
    for key in values:
        value = str(values[key])
        if not all(character.isalnum() or character in "-_" for character in value):
            frappe.throw("Invalid payment return reference")
        parts.append(key + "=" + value)
    return "&".join(parts)

def checkout_url(value, environment):
    host = "cybqa.pesapal.com" if environment == "sandbox" else "pay.pesapal.com"
    if not isinstance(value, str) or not value.startswith("https://" + host + "/") or "\\" in value or "\n" in value or "\r" in value:
        frappe.throw("Invalid checkout address")
    return value

def verified_status(payload, reference, amount, currency):
    if str(payload.get("status")) != "200" or payload.get("merchant_reference") != reference:
        frappe.throw("Payment reference mismatch")
    if payload.get("currency") != currency or money(payload.get("amount")) != money(amount):
        frappe.throw("Payment amount or currency mismatch")
    states = {0: "Pending", 1: "Paid", 2: "Failed", 3: "Reversed"}
    state = states.get(int(payload.get("status_code", -1)))
    if not state or (state == "Paid" and not payload.get("confirmation_code")):
        frappe.throw("Unverified provider payment status")
    return state

def ddconfig():
    settings = frappe.get_doc("DD Payment Settings")
    if not settings.enabled:
        frappe.throw("Payment checkout is not enabled yet")
    environment = settings.environment
    if environment not in ["sandbox", "live"]:
        frappe.throw("Select sandbox or live")
    origin = (settings.customer_origin or "").rstrip("/")
    local_return = environment == "sandbox" and settings.allow_local_return and origin in ["http://localhost:3000", "http://127.0.0.1:3000"]
    if not local_return and (not origin.startswith("https://") or "/" in origin[8:] or "@" in origin or "?" in origin or "#" in origin):
        frappe.throw("Configure the HTTPS website origin in DD Payment Settings")
    key = settings.get_password(environment + "_consumer_key", raise_exception=False)
    secret = settings.get_password(environment + "_consumer_secret", raise_exception=False)
    if not key or not secret:
        frappe.throw("Configure Pesapal credentials in DD Payment Settings")
    notification = settings.get(environment + "_ipn_id")
    base = "https://cybqa.pesapal.com/pesapalv3/api" if environment == "sandbox" else "https://pay.pesapal.com/v3/api"
    return environment, origin, key, secret, notification, base

def ddprovider(path, body=None, params=None):
    config = ddconfig()
    key = config[2]
    secret = config[3]
    base = config[5]
    token_result = frappe.make_post_request(base + "/Auth/RequestToken", data=json.dumps({"consumer_key": key, "consumer_secret": secret}), headers={"Content-Type": "application/json", "Accept": "application/json"})
    if str(token_result.get("status")) != "200" or not token_result.get("token"):
        frappe.throw("Pesapal authentication failed")
    headers = {"Authorization": "Bearer " + token_result["token"], "Content-Type": "application/json", "Accept": "application/json"}
    if body is not None:
        result = frappe.make_post_request(base + path, data=json.dumps(body), headers=headers)
    else:
        result = frappe.make_get_request(base + path, params=params, headers=headers)
    if str(result.get("status")) != "200":
        frappe.throw("Pesapal could not complete this action")
    return result

def csrf():
    staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
    account = frappe.session.user if staff else ddcustomer()
    doctype = "User" if staff else "DD Customer Account"
    token = frappe.utils.generate_hash(length=48)
    frappe.db.set_value(doctype, account, {"portal_csrf_hash": frappe.utils.sha256_hash(token), "portal_csrf_expires": frappe.utils.add_to_date(now_datetime(), minutes=10)})
    frappe.db.commit()
    return {"csrf_token": frappe.session.csrf_token or "", "mutation_token": token}

def mutation_proof():
    staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
    account = frappe.get_doc("User", frappe.session.user) if staff else frappe.get_doc("DD Customer Account", ddcustomer())
    token = frappe.form_dict.get("portal_csrf_token")
    if not isinstance(token, str) or len(token) != 48 or frappe.utils.sha256_hash(token) != account.portal_csrf_hash or not account.portal_csrf_expires or frappe.utils.get_datetime(account.portal_csrf_expires) < now_datetime():
        frappe.throw("Refresh your account session before making changes", frappe.PermissionError)

def register_ipn():
    if "System Manager" not in roles():
        frappe.throw("Not permitted", frappe.PermissionError)
    url = "https://thenetwork.frappe.cloud/api/method/dd_payment_ipn"
    result = ddprovider("/URLSetup/RegisterIPN", {"url": url, "ipn_notification_type": "GET"})
    if not result.get("ipn_id"):
        frappe.throw("Pesapal did not return a notification ID")
    environment = ddconfig()[0]
    frappe.db.set_value("DD Payment Settings", "DD Payment Settings", environment + "_ipn_id", result["ipn_id"])
    return {"success": True, "ipn_id": result["ipn_id"], "url": url}

def ddlock(doctype, name):
    frappe.db.sql(f'SELECT name FROM `tab{doctype}` WHERE name=%s FOR UPDATE', (name,))

def ddcustomer():
    user = frappe.session.user
    if user == 'Guest' or not frappe.db.get_value('User', user, 'enabled'):
        frappe.throw('Please sign in', frappe.PermissionError)
    account = frappe.db.get_value('DD Customer Account', {'user': user, 'email_verified': 1}, 'name')
    if not account or 'DD Customer' not in roles(user):
        frappe.throw('Verified customer account required', frappe.PermissionError)
    return account

def ddowned(reference):
    account = ddcustomer()
    if not frappe.db.exists('Diaspora Request', {'name': reference, 'dd_customer_account': account}):
        frappe.throw('Request not found', frappe.PermissionError)
    return frappe.get_doc('Diaspora Request', reference)

def validate_quote(doc, method=None):
    previous = doc.get_doc_before_save()
    if previous and previous.status != 'Draft':
        frappe.throw('Issued quotations are locked; prepare a new quotation for changed scope')
    if doc.status not in ('Draft', 'Issued'):
        frappe.throw('Quotation status is managed by the payment service')
    if doc.get('accepted_by') or doc.get('accepted_at'):
        frappe.throw('Acceptance is recorded only through customer approval')
    request = frappe.get_doc('Diaspora Request', doc.request)
    request.check_permission('read')
    ddlock('Diaspora Request', request.name)
    if doc.status == 'Issued' and frappe.db.exists('DD Quotation', {'request': doc.request, 'status': ['in', ['Issued', 'Accepted']], 'name': ['!=', doc.name or '']}):
        frappe.throw('A current quotation already exists; withdraw the unpaid quote before issuing a replacement')
    sequence_value_1 = (request.full_name, request.email)
    doc.customer_name = sequence_value_1[0]
    doc.customer_email = sequence_value_1[1]
    if doc.currency not in ('KES', 'USD', 'GBP', 'EUR'):
        frappe.throw('Unsupported quotation currency')
    if not doc.items or getdate(doc.valid_until) < getdate(doc.quotation_date):
        frappe.throw('Add projects and a valid quotation expiry')
    sequence_value_2 = (set(), money(0))
    seen = sequence_value_2[0]
    total = sequence_value_2[1]
    for item in doc.items:
        field = frappe.get_doc('Field Request', item.field_request)
        if field.diaspora_request != doc.request or field.name in seen:
            frappe.throw('Include each quoted project once, from this request')
        seen.add(field.name)
        count = item.get('planned_scouts')
        if isinstance(count, bool) or not count or float(count) != int(count) or (not 1 <= int(count) <= 20):
            frappe.throw('Enter a planned scout count from 1 to 20 for every project')
        if float(item.quantity) <= 0:
            frappe.throw('Quantity must be positive')
        item.project_title = field.project_title or field.request_type
        item.description = item.description or field.field_brief
        if not item.description:
            frappe.throw('Describe the agreed scope for every project')
        item.amount = float(money(money(item.rate) * money(item.quantity)))
        total += money(item.amount)
    if doc.status == 'Issued' and (not doc.terms):
        frappe.throw('Add the terms before issuing this quotation')
    sequence_value_3 = instalments(total)
    deposit = sequence_value_3[0]
    balance = sequence_value_3[1]
    sequence_value_4 = (float(total), float(deposit), float(balance))
    doc.total = sequence_value_4[0]
    doc.deposit_amount = sequence_value_4[1]
