def run_workflow():
    # RestrictedPython-compatible helpers for the production script runtime.
    def roles(user=None):
        return frappe.get_all("Has Role", filters={"parent": user or frappe.session.user, "parenttype": "User"}, pluck="role")
    
    def zip(left, right):
        return [(left[index], right[index]) for index in range(min(len(left), len(right)))]
    
    def money(value):
        text = str(value).strip()
        number = float(text)
        if number != number or number < 0 or number > 1000000000:
            frappe.throw("Invalid monetary amount")
        if "e" in text.lower():
            text = f"{number:.12f}"
        parts = text.lstrip("+-").split(".")
        fraction = parts[1] if len(parts) > 1 else ""
        cents = int(parts[0] or "0") * 100 + int((fraction + "00")[:2])
        if len(fraction) > 2 and fraction[2] >= "5":
            cents += 1
        return cents / 100.0
    
    def instalments(total):
        cents = int(round(money(total) * 100))
        if cents < 2:
            frappe.throw("Quotation must allow two positive payments")
        first = (cents + 1) // 2
        return first / 100.0, (cents - first) / 100.0
    
    def getdate(value=None):
        return frappe.utils.getdate(value) if value else frappe.utils.getdate()
    
    def now_datetime():
        return frappe.utils.now_datetime()
    
    def urlencode(values):
        parts = []
        for key in values:
            value = str(values[key])
            if not all(character.isalnum() or character in "-_" for character in value):
                frappe.throw("Invalid payment return reference")
            parts.append(key + "=" + value)
        return "&".join(parts)
    
    def checkout_url(value, environment):
        host = "cybqa.pesapal.com" if environment == "sandbox" else "pay.pesapal.com"
        if not isinstance(value, str) or not value.startswith("https://" + host + "/") or "\\" in value or "\n" in value or "\r" in value:
            frappe.throw("Invalid checkout address")
        return value
    
    def verified_status(payload, reference, amount, currency):
        if str(payload.get("status")) != "200" or payload.get("merchant_reference") != reference:
            frappe.throw("Payment reference mismatch")
        if payload.get("currency") != currency or money(payload.get("amount")) != money(amount):
            frappe.throw("Payment amount or currency mismatch")
        states = {0: "Pending", 1: "Paid", 2: "Failed", 3: "Reversed"}
        state = states.get(int(payload.get("status_code", -1)))
        if not state or (state == "Paid" and not payload.get("confirmation_code")):
            frappe.throw("Unverified provider payment status")
        return state
    
    def ddconfig():
        settings = frappe.get_doc("DD Payment Settings")
        if not settings.enabled:
            frappe.throw("Payment checkout is not enabled yet")
        environment = settings.environment
        if environment not in ["sandbox", "live"]:
            frappe.throw("Select sandbox or live")
        origin = (settings.customer_origin or "").rstrip("/")
        local_return = environment == "sandbox" and settings.allow_local_return and origin in ["http://localhost:3000", "http://127.0.0.1:3000"]
        if not local_return and (not origin.startswith("https://") or "/" in origin[8:] or "@" in origin or "?" in origin or "#" in origin):
            frappe.throw("Configure the HTTPS website origin in DD Payment Settings")
        key = settings.get_password(environment + "_consumer_key", raise_exception=False)
        secret = settings.get_password(environment + "_consumer_secret", raise_exception=False)
        if not key or not secret:
            frappe.throw("Configure Pesapal credentials in DD Payment Settings")
        notification = settings.get(environment + "_ipn_id")
        base = "https://cybqa.pesapal.com/pesapalv3/api" if environment == "sandbox" else "https://pay.pesapal.com/v3/api"
        return environment, origin, key, secret, notification, base
    
    def ddprovider(path, body=None, params=None):
        config = ddconfig()
        key = config[2]
        secret = config[3]
        base = config[5]
        token_result = frappe.make_post_request(base + "/Auth/RequestToken", data=json.dumps({"consumer_key": key, "consumer_secret": secret}), headers={"Content-Type": "application/json", "Accept": "application/json"})
        if str(token_result.get("status")) != "200" or not token_result.get("token"):
            frappe.throw("Pesapal authentication failed")
        headers = {"Authorization": "Bearer " + token_result["token"], "Content-Type": "application/json", "Accept": "application/json"}
        if body is not None:
            result = frappe.make_post_request(base + path, data=json.dumps(body), headers=headers)
        else:
            result = frappe.make_get_request(base + path, params=params, headers=headers)
        if str(result.get("status")) != "200":
            frappe.throw("Pesapal could not complete this action")
        return result
    
    def csrf():
        staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
        account = frappe.session.user if staff else ddcustomer()
        doctype = "User" if staff else "DD Customer Account"
        token = frappe.utils.generate_hash(length=48)
        frappe.db.set_value(doctype, account, {"portal_csrf_hash": frappe.utils.sha256_hash(token), "portal_csrf_expires": frappe.utils.add_to_date(now_datetime(), minutes=10)})
        frappe.db.commit()
        return {"csrf_token": frappe.session.csrf_token or "", "mutation_token": token}
    
    def mutation_proof():
        staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
        account = frappe.get_doc("User", frappe.session.user) if staff else frappe.get_doc("DD Customer Account", ddcustomer())
        token = frappe.form_dict.get("portal_csrf_token")
        if not isinstance(token, str) or len(token) != 48 or frappe.utils.sha256_hash(token) != account.portal_csrf_hash or not account.portal_csrf_expires or frappe.utils.get_datetime(account.portal_csrf_expires) < now_datetime():
            frappe.throw("Refresh your account session before making changes", frappe.PermissionError)
    
    def register_ipn():
        if "System Manager" not in roles():
            frappe.throw("Not permitted", frappe.PermissionError)
        url = "https://thenetwork.frappe.cloud/api/method/dd_payment_ipn"
        result = ddprovider("/URLSetup/RegisterIPN", {"url": url, "ipn_notification_type": "GET"})
        if not result.get("ipn_id"):
            frappe.throw("Pesapal did not return a notification ID")
        environment = ddconfig()[0]
        frappe.db.set_value("DD Payment Settings", "DD Payment Settings", environment + "_ipn_id", result["ipn_id"])
        return {"success": True, "ipn_id": result["ipn_id"], "url": url}
    
    def ddlock(doctype, name):
        frappe.db.sql(f'SELECT name FROM `tab{doctype}` WHERE name=%s FOR UPDATE', (name,))
    
    def ddcustomer():
        user = frappe.session.user
        if user == 'Guest' or not frappe.db.get_value('User', user, 'enabled'):
            frappe.throw('Please sign in', frappe.PermissionError)
        account = frappe.db.get_value('DD Customer Account', {'user': user, 'email_verified': 1}, 'name')
        if not account or 'DD Customer' not in roles(user):
            frappe.throw('Verified customer account required', frappe.PermissionError)
        return account
    
    def ddowned(reference):
        account = ddcustomer()
        if not frappe.db.exists('Diaspora Request', {'name': reference, 'dd_customer_account': account}):
            frappe.throw('Request not found', frappe.PermissionError)
        return frappe.get_doc('Diaspora Request', reference)
    
    def validate_quote(doc, method=None):
        previous = doc.get_doc_before_save()
        if previous and previous.status != 'Draft':
            frappe.throw('Issued quotations are locked; prepare a new quotation for changed scope')
        if doc.status not in ('Draft', 'Issued'):
            frappe.throw('Quotation status is managed by the payment service')
        if doc.get('accepted_by') or doc.get('accepted_at'):
            frappe.throw('Acceptance is recorded only through customer approval')
        request = frappe.get_doc('Diaspora Request', doc.request)
        request.check_permission('read')
        ddlock('Diaspora Request', request.name)
        if doc.status == 'Issued' and frappe.db.exists('DD Quotation', {'request': doc.request, 'status': ['in', ['Issued', 'Accepted']], 'name': ['!=', doc.name or '']}):
            frappe.throw('A current quotation already exists; withdraw the unpaid quote before issuing a replacement')
        sequence_value_1 = (request.full_name, request.email)
        doc.customer_name = sequence_value_1[0]
        doc.customer_email = sequence_value_1[1]
        if doc.currency not in ('KES', 'USD', 'GBP', 'EUR'):
            frappe.throw('Unsupported quotation currency')
        if not doc.items or getdate(doc.valid_until) < getdate(doc.quotation_date):
            frappe.throw('Add projects and a valid quotation expiry')
        sequence_value_2 = (set(), money(0))
        seen = sequence_value_2[0]
        total = sequence_value_2[1]
        for item in doc.items:
            field = frappe.get_doc('Field Request', item.field_request)
            if field.diaspora_request != doc.request or field.name in seen:
                frappe.throw('Include each quoted project once, from this request')
            seen.add(field.name)
            count = item.get('planned_scouts')
            if isinstance(count, bool) or not count or float(count) != int(count) or (not 1 <= int(count) <= 20):
                frappe.throw('Enter a planned scout count from 1 to 20 for every project')
            if float(item.quantity) <= 0:
                frappe.throw('Quantity must be positive')
            item.project_title = field.project_title or field.request_type
            item.description = item.description or field.field_brief
            if not item.description:
                frappe.throw('Describe the agreed scope for every project')
            item.amount = float(money(money(item.rate) * money(item.quantity)))
            total += money(item.amount)
        if doc.status == 'Issued' and (not doc.terms):
            frappe.throw('Add the terms before issuing this quotation')
        sequence_value_3 = instalments(total)
        deposit = sequence_value_3[0]
        balance = sequence_value_3[1]
        sequence_value_4 = (float(total), float(deposit), float(balance))
        doc.total = sequence_value_4[0]
        doc.deposit_amount = sequence_value_4[1]
        doc.balance_amount = sequence_value_4[2]
        doc.deposit_percent = 50
        doc.version = 1
    
    def ddquote(reference):
        name = frappe.db.get_value('DD Quotation', {'request': reference, 'status': ['in', ['Issued', 'Accepted']]}, 'name', order_by='creation desc')
        return frappe.get_doc('DD Quotation', name) if name else None
    
    def ddobligations(quote):
        return frappe.get_all('DD Payment', filters={'quotation': quote.name}, fields=['name', 'kind', 'amount', 'currency', 'status'], order_by='creation asc')
    
    def ddbilling(request):
        quote = ddquote(request.name)
        if not quote:
            return {'quote': None, 'payments': [], 'documents': []}
        projects = []
        for item in quote.items:
            scouts = frappe.get_all('Field Task', filters={'field_request': item.field_request, 'status': ['!=', 'Cancelled']}, pluck='scout_profile')
            projects.append({'project': item.field_request, 'title': item.project_title, 'scope': item.description, 'planned_scouts': item.get('planned_scouts'), 'assigned_scouts': len(set(scouts)), 'amount': float(item.amount)})
        payments = ddobligations(quote)
        deposit_paid = any((p.kind == 'deposit' and p.status == 'Paid' for p in payments))
        for payment in payments:
            payment.amount = float(payment.amount)
            payment.can_pay = quote.status == 'Accepted' and payment.status != 'Paid' and (payment.kind == 'deposit' or (deposit_paid and request.status == 'Completed'))
        return {'quote': {'name': quote.name, 'version': quote.get('version') or 1, 'status': quote.status, 'currency': quote.currency, 'total': float(quote.total), 'deposit_amount': quote.get('deposit_amount'), 'balance_amount': quote.get('balance_amount'), 'valid_until': quote.valid_until, 'terms': quote.terms, 'scope': '\n'.join((item.description for item in quote.items)), 'projects': projects, 'can_accept': quote.status == 'Issued' and bool(quote.get('deposit_amount')) and (getdate(quote.valid_until) >= getdate())}, 'payments': payments, 'documents': []}
    
    def billing(reference=None):
        if reference:
            return {'billing': ddbilling(ddowned(reference))}
        account = ddcustomer()
        requests_ = frappe.get_all('Diaspora Request', filters={'dd_customer_account': account}, fields=['name', 'summary'], limit_page_length=200)
        return {'requests': [{'name': row.name, 'title': row.summary, 'billing': ddbilling(frappe.get_doc('Diaspora Request', row.name))} for row in requests_]}
    
    def accept_quote(reference, quote, version, submission_id):
        request = ddowned(reference)
        ddlock('Diaspora Request', request.name)
        current = ddquote(reference)
        if not current or current.name != quote or str(current.get('version') or 1) != str(version):
            frappe.throw('This quotation has changed')
        if current.status == 'Accepted':
            return {'success': True}
        if getdate(current.valid_until) < getdate() or not current.get('deposit_amount'):
            frappe.throw('This quotation needs to be reissued before acceptance')
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw('Invalid acceptance reference')
        frappe.db.set_value('DD Quotation', current.name, {'status': 'Accepted', 'accepted_by': frappe.session.user, 'accepted_at': now_datetime(), 'acceptance_reference': submission_id})
        for sequence_item_1 in zip(('deposit', 'balance'), instalments(current.total)):
            kind = sequence_item_1[0]
            amount = sequence_item_1[1]
            frappe.get_doc({'doctype': 'DD Payment', 'request': reference, 'quotation': current.name, 'kind': kind, 'amount': float(amount), 'currency': current.currency, 'status': 'Unpaid'}).insert(ignore_permissions=True)
        return {'success': True}
    
    def checkout(reference, payment, submission_id, return_origin=None):
        request = ddowned(reference)
        ddlock('Diaspora Request', request.name)
        obligation = frappe.get_doc('DD Payment', payment)
        quote = ddquote(reference)
        if not quote or quote.status != 'Accepted' or obligation.request != reference or (obligation.quotation != quote.name):
            frappe.throw('Payment does not belong to the accepted quotation', frappe.PermissionError)
        if obligation.status == 'Paid':
            frappe.throw('This payment is already complete')
        if obligation.kind == 'balance' and (request.status != 'Completed' or not frappe.db.exists('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'})):
            frappe.throw('The balance is payable after completion and verified deposit')
        sequence_value_1 = ddconfig()
        environment = sequence_value_1[0]
        origin = sequence_value_1[1]
        dd = sequence_value_1[2]
        dd = sequence_value_1[3]
        notification = sequence_value_1[4]
        dd = sequence_value_1[5]
        if return_origin and return_origin != origin:
            if environment != 'sandbox' or return_origin not in ('http://localhost:3000', 'http://127.0.0.1:3000') or (not frappe.db.get_single_value('DD Payment Settings', 'allow_local_return')):
                frappe.throw('Checkout return origin is not authorised')
            origin = return_origin
        if obligation.currency not in ([value.strip() for value in (frappe.db.get_single_value('DD Payment Settings', 'enabled_currencies') or 'KES').split(',')] or ['KES']):
            frappe.throw('This currency has not been enabled for checkout')
        if not notification:
            frappe.throw('Register the Pesapal notification endpoint first')
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw('Invalid checkout reference')
        active = frappe.db.get_value('DD Payment Attempt', {'payment': payment, 'status': ['in', ['Creating', 'Pending', 'Review']]}, 'name')
        if active:
            attempt = frappe.get_doc('DD Payment Attempt', active)
            if attempt.environment != environment or not attempt.checkout_url:
                frappe.throw('An earlier checkout is being reconciled. Please contact support before retrying')
            return {'checkout_url': checkout_url(attempt.checkout_url, environment)}
        merchant_reference = 'DD-' + frappe.utils.generate_hash(length=32)
        attempt = frappe.get_doc({'doctype': 'DD Payment Attempt', 'payment': payment, 'merchant_reference': merchant_reference, 'environment': environment, 'amount': obligation.amount, 'currency': obligation.currency, 'status': 'Creating', 'submission_id': submission_id}).insert(ignore_permissions=True)
        frappe.db.commit()
        try:
            result = ddprovider('/Transactions/SubmitOrderRequest', {'id': merchant_reference, 'currency': obligation.currency, 'amount': float(obligation.amount), 'description': f'Diaspora Desk {obligation.kind}', 'notification_id': notification, 'callback_url': origin + '/dashboard/billing?' + urlencode({'payment_return': '1', 'request': reference}), 'billing_address': {'email_address': frappe.session.user}})
            if result.get('merchant_reference') != merchant_reference or not result.get('order_tracking_id'):
                raise ValueError('Unexpected provider order')
            url = checkout_url(result.get('redirect_url'), environment)
            ddlock('DD Payment Attempt', attempt.name)
            attempt.reload()
            if attempt.tracking_id and attempt.tracking_id != result['order_tracking_id']:
                raise ValueError('Provider tracking conflict')
            frappe.db.set_value('DD Payment Attempt', attempt.name, {'tracking_id': result['order_tracking_id'], 'checkout_url': url, 'status': attempt.status if attempt.status in ('Paid', 'Reversed', 'Failed') else 'Pending'})
            return {'checkout_url': url}
        except Exception:
            ddlock('DD Payment Attempt', attempt.name)
            attempt.reload()
            if attempt.status not in ('Paid', 'Reversed'):
                frappe.db.set_value('DD Payment Attempt', attempt.name, 'status', 'Review')
            frappe.db.commit()
            frappe.throw('Checkout needs reconciliation. Please contact support before retrying')
    
    def ddverify(attempt_name, tracking_id=None):
        attempt = frappe.get_doc('DD Payment Attempt', attempt_name)
        tracking_id = tracking_id or attempt.tracking_id
        if not tracking_id:
            return
        if attempt.environment != ddconfig()[0]:
            frappe.throw('Configure the original payment environment to reconcile this attempt')
        data = ddprovider('/Transactions/GetTransactionStatus', params={'orderTrackingId': tracking_id})
        state = verified_status(data, attempt.merchant_reference, attempt.amount, attempt.currency)
        payment = frappe.get_doc('DD Payment', attempt.payment)
        ddlock('Diaspora Request', payment.request)
        ddlock('DD Payment', payment.name)
        attempt.reload()
        payment.reload()
        if attempt.status == 'Paid' and state in ('Pending', 'Failed'):
            return
        frappe.db.set_value('DD Payment Attempt', attempt.name, {'tracking_id': tracking_id, 'status': state, 'confirmation_code': data.get('confirmation_code'), 'verified_at': now_datetime()})
        if state == 'Paid':
            if payment.status == 'Paid' and payment.get('paid_attempt') != attempt.name:
                frappe.db.set_value('DD Payment Attempt', attempt.name, 'status', 'Review')
                return
            frappe.db.set_value('DD Payment', payment.name, {'status': 'Paid', 'paid_attempt': attempt.name, 'paid_at': now_datetime()})
        elif state == 'Reversed' and payment.get('paid_attempt') == attempt.name:
            frappe.db.set_value('DD Payment', payment.name, 'status', 'Reversed')
    
    def ipn(OrderTrackingId=None, OrderMerchantReference=None, OrderNotificationType=None):
        if not isinstance(OrderTrackingId, str) or len(OrderTrackingId) > 100 or (not isinstance(OrderMerchantReference, str)) or (len(OrderMerchantReference) > 50):
            frappe.throw('Invalid notification')
        name = frappe.db.get_value('DD Payment Attempt', {'merchant_reference': OrderMerchantReference}, 'name')
        if not name:
            frappe.throw('Unknown payment')
        attempt = frappe.get_doc('DD Payment Attempt', name)
        if attempt.tracking_id and attempt.tracking_id != OrderTrackingId:
            frappe.throw('Payment reference mismatch')
        try:
            ddverify(name, OrderTrackingId)
            frappe.db.commit()
        except Exception:
            frappe.db.rollback()
            frappe.response.update({'orderNotificationType': 'IPNCHANGE', 'orderTrackingId': OrderTrackingId, 'orderMerchantReference': OrderMerchantReference, 'status': 500})
            return
        frappe.response.update({'orderNotificationType': 'IPNCHANGE', 'orderTrackingId': OrderTrackingId, 'orderMerchantReference': OrderMerchantReference, 'status': 200})
    
    def refresh(reference):
        ddowned(reference)
        attempts = frappe.db.sql("SELECT a.name FROM `tabDD Payment Attempt` a\n        INNER JOIN `tabDD Payment` p ON a.payment=p.name\n        WHERE p.request=%s AND a.tracking_id IS NOT NULL AND a.status IN ('Pending','Review') LIMIT 10", (reference,), as_dict=True)
        for attempt in attempts:
            ddverify(attempt.name)
        return {'success': True}
    
    def reconcile():
        for row in frappe.get_all('DD Payment Attempt', filters={'status': ['in', ['Pending', 'Review']], 'tracking_id': ['is', 'set']}, pluck='name', limit_page_length=100, order_by='modified asc'):
            try:
                ddverify(row)
                frappe.db.commit()
            except Exception:
                frappe.db.rollback()
                frappe.log_error(title='Pesapal reconciliation failed', message=f'Review payment attempt {row}; provider verification did not complete.')
    
    def require_deposit(doc, method=None):
        if not doc.field_request:
            return
        previous = doc.get_doc_before_save()
        entering = doc.is_new() or (previous and (previous.scout_profile != doc.scout_profile or previous.field_request != doc.field_request or (previous.status == 'Cancelled' and doc.status != 'Cancelled')))
        if not entering or doc.status == 'Cancelled':
            return
        reference = frappe.db.get_value('Field Request', doc.field_request, 'diaspora_request')
        if not reference:
            return
        ddlock('Diaspora Request', reference)
        quote = ddquote(reference)
        if not quote or quote.status != 'Accepted' or (not frappe.db.exists('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'})):
            frappe.throw('Accept the quotation and verify the 50% deposit before assigning scouts')
        paid_attempt = frappe.db.get_value('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'}, 'paid_attempt')
        environment = frappe.db.get_value('DD Payment Attempt', paid_attempt, 'environment') if paid_attempt else None
        if environment != 'live' and (not (environment == 'sandbox' and frappe.db.get_single_value('DD Payment Settings', 'allow_sandbox_dispatch') and frappe.db.get_value('Diaspora Request', reference, 'sandbox_testing'))):
            frappe.throw('A live verified deposit is required for dispatch; sandbox dispatch must be explicitly enabled on a test site')
        line = None
        for row in quote.items:
            if row.field_request == doc.field_request:
                line = row
                break
        if not line:
            frappe.throw('This project is not included in the paid quotation')
        scouts = set(frappe.get_all('Field Task', filters={'field_request': doc.field_request, 'name': ['!=', doc.name or ''], 'status': ['!=', 'Cancelled']}, pluck='scout_profile'))
        scouts.add(doc.scout_profile)
        if len(scouts) > int(line.planned_scouts):
            frappe.throw('Scout count exceeds the accepted quotation; review the agreed scope first')
    
    def withdraw_quote(quote):
        document = frappe.get_doc('DD Quotation', quote)
        document.check_permission('write')
        ddlock('Diaspora Request', document.request)
        document.reload()
        if document.status != 'Issued' or frappe.db.exists('DD Payment', {'quotation': document.name}):
            frappe.throw('Only an unaccepted quotation can be withdrawn; accepted work needs a reviewed amendment')
        frappe.db.set_value('DD Quotation', document.name, 'status', 'Withdrawn')
        return {'success': True}

    def disputes(reference=None):
        account = ddcustomer()
        filters = {"customer_account": account}
        if reference:
            ddowned(reference)
            filters["request"] = reference
        rows = frappe.get_all("DD Dispute", filters=filters, fields=["name", "request", "subject", "reason", "status", "modified", "response"], order_by="modified desc", limit_page_length=200)
        return {"disputes": rows}

    def create_dispute(reference, subject, reason, submission_id):
        request = ddowned(reference)
        ddlock("Diaspora Request", request.name)
        if not isinstance(subject, str) or not 1 <= len(subject.strip()) <= 140 or not isinstance(reason, str) or not 20 <= len(reason.strip()) <= 4000:
            frappe.throw("Describe the issue with a subject and 20 to 4000 characters")
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw("Invalid dispute reference")
        existing = frappe.db.get_value("DD Dispute", {"request": reference, "submission_id": submission_id}, "name")
        if existing:
            return {"success": True, "dispute": {"name": existing}}
        document = frappe.get_doc({"doctype": "DD Dispute", "request": reference, "customer_account": ddcustomer(),
            "subject": subject.strip(), "reason": reason.strip(), "submission_id": submission_id, "status": "Open"})
        document.insert(ignore_permissions=True)
        return {"success": True, "dispute": {"name": document.name}}

    def validate_dispute(doc):
        request = frappe.get_doc("Diaspora Request", doc.request)
        if request.dd_customer_account != doc.customer_account:
            frappe.throw("Dispute ownership does not match the request")
        previous = doc.get_doc_before_save()
        if not previous:
            if doc.status != "Open" or doc.response:
                frappe.throw("New disputes must start Open, without a staff response")
        else:
            for key in ["request", "customer_account", "subject", "reason", "submission_id"]:
                if doc.get(key) != previous.get(key):
                    frappe.throw("Original dispute details cannot be replaced")
            transitions = {"Open": ["Under review", "Awaiting customer", "Resolved"], "Under review": ["Awaiting customer", "Resolved"], "Awaiting customer": ["Under review", "Resolved"], "Resolved": ["Under review", "Closed"], "Closed": ["Under review"]}
            if doc.status != previous.status and doc.status not in transitions.get(previous.status, []):
                frappe.throw("Invalid dispute transition")
            if doc.status in ["Resolved", "Closed"] and not (doc.response or "").strip():
                frappe.throw("Provide the customer-visible resolution before resolving the dispute")
        # Preserve history: staff editing the form cannot erase previous review events.
        events = []
        if previous:
            for event in previous.get("history") or []:
                events.append({"status": event.status, "response": event.response, "actor": event.actor, "recorded_at": event.recorded_at})
        if not previous or previous.status != doc.status or previous.response != doc.response:
            events.append({"status": doc.status, "response": doc.response, "actor": frappe.session.user, "recorded_at": now_datetime()})
        doc.set("history", events)
        if doc.status in ["Resolved", "Closed"]:
            doc.resolved_at = previous.resolved_at if previous and previous.resolved_at else now_datetime()

    def report(reference):
        ddowned(reference)
        name = frappe.db.get_value("DD Service Report", {"request": reference, "status": "Approved"}, "name", order_by="creation desc")
        if not name:
            return {"report": None}
        doc = frappe.get_doc("DD Service Report", name)
        return {"report": {"name": name, "title": doc.title, "released": True, "approved_at": doc.approved_at,
            "download_url": "/api/customer/requests/" + reference + "/report"}}

    def download_report(reference):
        result = report(reference)
        if not result["report"]:
            frappe.throw("An approved report is not yet available")
        doc = frappe.get_doc("DD Service Report", result["report"]["name"])
        file_name = frappe.db.get_value("File", {"file_url": doc.report_file, "is_private": 1}, "name")
        if not file_name:
            frappe.throw("Private report file is unavailable")
        file = frappe.get_doc("File", file_name)
        frappe.response["type"] = "download"
        frappe.response["filename"] = file.file_name
        frappe.response["filecontent"] = file.get_content()
        frappe.response["display_content_as"] = "attachment"

    def validate_report(doc):
        previous = doc.get_doc_before_save()
        if previous and previous.status == "Approved":
            frappe.throw("Approved reports are locked; prepare a new version for corrections")
        if doc.status == "Approved":
            if "Field Operations Coordinator" not in roles() and "System Manager" not in roles():
                frappe.throw("Only a coordinator can approve a report", frappe.PermissionError)
            if not doc.report_file or not frappe.db.exists("File", {"file_url": doc.report_file, "is_private": 1}):
                frappe.throw("Attach a private report file before approval")
            file_name = frappe.db.get_value("File", {"file_url": doc.report_file, "is_private": 1}, "name")
            file = frappe.get_doc("File", file_name)
            if not file.file_name.lower().endswith(".pdf") or (file.file_size or 0) > 20000000:
                frappe.throw("Approved customer reports must be private PDF files up to 20 MB")
            if frappe.db.get_value("Diaspora Request", doc.request, "status") != "Completed":
                frappe.throw("Approve the field work and complete the request before approving its report")
            doc.approved_by = frappe.session.user
            doc.approved_at = now_datetime()

    def update_settings(full_name, phone, timezone, email_notifications):
        account = ddcustomer()
        if not isinstance(full_name, str) or not 1 <= len(full_name.strip()) <= 140 or not isinstance(phone, str) or len(phone) > 30:
            frappe.throw("Enter a valid name and phone number")
        allowed = ["Africa/Nairobi", "Europe/London", "Europe/Paris", "America/New_York", "America/Chicago", "America/Los_Angeles", "Asia/Dubai", "Australia/Sydney", "UTC"]
        if timezone not in allowed or not isinstance(email_notifications, bool):
            frappe.throw("Invalid timezone or notification preference")
        user = frappe.get_doc("User", frappe.session.user)
        user.first_name = full_name.strip()
        user.last_name = ""
        user.time_zone = timezone
        user.mobile_no = phone.strip()
        user.save(ignore_permissions=True)
        frappe.db.set_value("DD Customer Account", account, "email_notifications", int(email_notifications))
        return {"success": True, "customer": {"id": account, "email": user.email, "full_name": user.full_name, "phone": user.mobile_no, "timezone": user.time_zone, "email_verified": True, "email_notifications": email_notifications}}

    def deletion_request(reason=""):
        account = ddcustomer()
        if not isinstance(reason, str) or len(reason) > 1000:
            frappe.throw("Reason must be at most 1000 characters")
        ddlock("DD Customer Account", account)
        name = frappe.db.get_value("DD Account Deletion", {"customer_account": account, "status": ["in", ["Open", "Under review"]]}, "name")
        if not name:
            doc = frappe.get_doc({"doctype": "DD Account Deletion", "customer_account": account, "reason": reason, "status": "Open"}).insert(ignore_permissions=True)
            name = doc.name
        return {"success": True, "reference": name}

    reconcile()
run_workflow()

# Shared source is embedded into each Frappe Server Script by the installer.
# No imports or filesystem access are used. User-facing assignment checks permissions.
def check_project_access(source):
    # No customer-record role permissions are added. Automation can use an
    # existing operational request only when the caller can write that request.
    allowed = source.has_permission("read")
    if not allowed:
        linked = frappe.get_all("Field Request", filters={"diaspora_request": source.name}, fields=["name"])
        for row in linked:
            request = frappe.get_doc("Field Request", row.name)
            if request.has_permission("write"):
                allowed = True
    if not allowed:
        frappe.throw("You cannot map projects from this customer request.", frappe.PermissionError)


def project_plan(source):
    counties = "Mombasa|Kwale|Kilifi|Tana River|Lamu|Taita Taveta|Garissa|Wajir|Mandera|Marsabit|Isiolo|Meru|Tharaka Nithi|Embu|Kitui|Machakos|Makueni|Nyandarua|Nyeri|Kirinyaga|Murang'a|Kiambu|Turkana|West Pokot|Samburu|Trans Nzoia|Uasin Gishu|Elgeyo Marakwet|Nandi|Baringo|Laikipia|Nakuru|Narok|Kajiado|Kericho|Bomet|Kakamega|Vihiga|Bungoma|Busia|Siaya|Kisumu|Homa Bay|Migori|Kisii|Nyamira|Nairobi".split("|")
    county_keys = {}
    for county in counties:
        county_keys["".join(c for c in county.lower() if c.isalpha())] = county
    projects = {}
    issues = []
    for detail in json.loads(source.get("project_details") or "[]"):
        number = detail.get("number")
        description = detail.get("description") or ""
        county = detail.get("county") or ""
        if not county:
            for candidate in counties:
                if candidate.lower() + " county" in description.lower():
                    county = candidate
        if number and description:
            projects[number] = {"number": number, "title": description, "county": county, "request_type": "General Site Visit", "evidence": [], "description": description, "scope_status": detail.get("location_question_status")}
    for row in source.get("evidence_checklist") or []:
        text = (row.get("evidence_item") or "").strip()
        number = 0
        title = ""
        county = ""
        if text.lower().startswith("project ") and "[" in text and "]" in text:
            prefix = text.split("[", 1)[0].strip().split()
            if len(prefix) == 2 and prefix[1].isdigit():
                number = int(prefix[1])
            label = text.split("[", 1)[1].split("]", 1)[0]
            # Intake labels may use a middle dot or a spaced dash.
            label = label.replace(" – ", "·").replace(" — ", "·").replace(" - ", "·")
            parts = label.split("·")
            if len(parts) == 2:
                title = parts[0].strip()
                raw_county = parts[1].lower().replace("county", "")
                county = county_keys.get("".join(c for c in raw_county if c.isalpha()), "")
        if not number or not title or not county:
            issues.append("An evidence item needs a confirmed project number, title and county.")
        else:
            project = projects.get(number)
            if project and (project["county"] and project["county"] != county or not project.get("description") and project["title"] != title):
                issues.append("Conflicting county or title for project " + str(number))
            if not project:
                request_type = {"land_property_check": "Property Verification", "construction_progress": "Construction Progress", "business_asset_check": "Business / Merchant Verification"}.get(source.get("category"), "General Site Visit")
                if title.upper() in ["SHOP", "SALON", "BUSINESS", "MERCHANT"]:
                    request_type = "Business / Merchant Verification"
                elif title.upper() == "LAND":
                    request_type = "Property Verification"
                elif title.upper() in ["HOUSE", "HOME", "PLOT", "PROPERTY"] and source.get("category") != "construction_progress":
                    request_type = "Property Verification"
                project = {"number": number, "title": title, "county": county, "request_type": request_type, "evidence": []}
                projects[number] = project
            project["county"] = county
            project["title"] = title
            project["evidence"].append(text)
    for project in projects.values():
        text = (project.get("description") or project["title"]).lower()
        if "construction" in text:
            project["request_type"] = "Construction Progress"
        elif any(word in text for word in ["salon", "shop", "business", "merchant"]):
            project["request_type"] = "Business / Merchant Verification"
        elif any(word in text for word in ["land", "house", "home", "plot", "property", "apartment"]):
            project["request_type"] = "Construction Progress" if source.get("category") == "construction_progress" else "Property Verification"
        project["review"] = 1 if not project["county"] or not project["evidence"] or project.get("scope_status") in ["needed", "scope_confirmation", "unsupported"] else 0
    deadline = None
    preference = source.get("deadline_preference")
    if preference == "specific":
        deadline = source.get("deadline_date")
    elif preference in ["oneWeek", "twoWeeks"]:
        deadline = frappe.utils.add_days(str(source.get("creation") or frappe.utils.now())[:10], 7 if preference == "oneWeek" else 14)
    return {"projects": [projects[number] for number in sorted(projects)], "issues": issues, "deadline": str(deadline)[:10] if deadline else None}


def fill_field_request(target, source, plan):
    if plan["issues"] or not plan["projects"]:
        target.alignment_review = 1
        return
    number = target.get("project_number") or plan["projects"][0]["number"]
    selected = None
    for project in plan["projects"]:
        if project["number"] == number:
            selected = project
    if not selected:
        frappe.throw("This project is no longer in the customer request. Coordinator review is required.")
    initial = not target.get("project_number")
    if initial and not target.is_new() and (target.status != "Awaiting Assignment" or frappe.db.exists("Field Task", {"field_request": target.name})):
        frappe.throw("An existing assignment cannot be split automatically. Review its project scope first.")
    target.project_number = selected["number"]
    target.project_title = selected["title"]
    target.project_key = source.name + ":" + str(number)
    target.county = selected["county"]
    target.deadline_preference = source.deadline_preference
    target.customer_target_date = plan["deadline"]
    target.alignment_review = selected["review"]
    if not target.deadline:
        target.deadline = plan["deadline"]
    if initial or target.status == "Awaiting Assignment" and not frappe.db.exists("Field Task", {"field_request": target.name}):
        target.request_type = selected["request_type"]
    target.evidence_requirements = "\n".join(selected["evidence"])
    if initial or target.status == "Awaiting Assignment" and not frappe.db.exists("Field Task", {"field_request": target.name}):
        timing = {"flexible": "No fixed customer deadline", "oneWeek": "Within one week of submission", "twoWeeks": "Within two weeks of submission", "specific": "By the customer's selected date"}.get(source.deadline_preference, "")
        brief = selected.get("description") or ""
        for paragraph in (source.summary or "").split("\n\n"):
            if paragraph.strip().lower().startswith("project " + str(number) + ":"):
                brief = paragraph.strip()
        if len(plan["projects"]) == 1 and not brief:
            brief = source.summary or ""
        target.field_brief = "Project " + str(number) + ": " + selected["title"] + " — " + selected["county"] + "\n\n" + brief + "\n\nEvidence required:\n" + target.evidence_requirements + "\n\nCustomer timing: " + timing + (" (" + plan["deadline"] + ")" if plan["deadline"] else "")

plan = project_plan(doc)
doc.customer_target_date = plan["deadline"]
doc.alignment_review = 1 if plan["issues"] or not plan["projects"] or any(project["review"] for project in plan["projects"]) else 0
if not plan["issues"] and plan["projects"]:
    counties = []
    for project in plan["projects"]:
        if project["county"] not in counties:
            counties.append(project["county"])
        for row in doc.evidence_checklist:
            if row.evidence_item.strip() in project["evidence"]:
                row.project_number = project["number"]
                row.county = project["county"]
    doc.county = ", ".join(counties)

def run_workflow(doc):
    # RestrictedPython-compatible helpers for the production script runtime.
    def roles(user=None):
        return frappe.get_all("Has Role", filters={"parent": user or frappe.session.user, "parenttype": "User"}, pluck="role")
    
    def zip(left, right):
        return [(left[index], right[index]) for index in range(min(len(left), len(right)))]
    
    def money(value):
        text = str(value).strip()
        number = float(text)
        if number != number or number < 0 or number > 1000000000:
            frappe.throw("Invalid monetary amount")
        if "e" in text.lower():
            text = f"{number:.12f}"
        parts = text.lstrip("+-").split(".")
        fraction = parts[1] if len(parts) > 1 else ""
        cents = int(parts[0] or "0") * 100 + int((fraction + "00")[:2])
        if len(fraction) > 2 and fraction[2] >= "5":
            cents += 1
        return cents / 100.0
    
    def instalments(total):
        cents = int(round(money(total) * 100))
        if cents < 2:
            frappe.throw("Quotation must allow two positive payments")
        first = (cents + 1) // 2
        return first / 100.0, (cents - first) / 100.0
    
    def getdate(value=None):
        return frappe.utils.getdate(value) if value else frappe.utils.getdate()
    
    def now_datetime():
        return frappe.utils.now_datetime()
    
    def urlencode(values):
        parts = []
        for key in values:
            value = str(values[key])
            if not all(character.isalnum() or character in "-_" for character in value):
                frappe.throw("Invalid payment return reference")
            parts.append(key + "=" + value)
        return "&".join(parts)
    
    def checkout_url(value, environment):
        host = "cybqa.pesapal.com" if environment == "sandbox" else "pay.pesapal.com"
        if not isinstance(value, str) or not value.startswith("https://" + host + "/") or "\\" in value or "\n" in value or "\r" in value:
            frappe.throw("Invalid checkout address")
        return value
    
    def verified_status(payload, reference, amount, currency):
        if str(payload.get("status")) != "200" or payload.get("merchant_reference") != reference:
            frappe.throw("Payment reference mismatch")
        if payload.get("currency") != currency or money(payload.get("amount")) != money(amount):
            frappe.throw("Payment amount or currency mismatch")
        states = {0: "Pending", 1: "Paid", 2: "Failed", 3: "Reversed"}
        state = states.get(int(payload.get("status_code", -1)))
        if not state or (state == "Paid" and not payload.get("confirmation_code")):
            frappe.throw("Unverified provider payment status")
        return state
    
    def ddconfig():
        settings = frappe.get_doc("DD Payment Settings")
        if not settings.enabled:
            frappe.throw("Payment checkout is not enabled yet")
        environment = settings.environment
        if environment not in ["sandbox", "live"]:
            frappe.throw("Select sandbox or live")
        origin = (settings.customer_origin or "").rstrip("/")
        local_return = environment == "sandbox" and settings.allow_local_return and origin in ["http://localhost:3000", "http://127.0.0.1:3000"]
        if not local_return and (not origin.startswith("https://") or "/" in origin[8:] or "@" in origin or "?" in origin or "#" in origin):
            frappe.throw("Configure the HTTPS website origin in DD Payment Settings")
        key = settings.get_password(environment + "_consumer_key", raise_exception=False)
        secret = settings.get_password(environment + "_consumer_secret", raise_exception=False)
        if not key or not secret:
            frappe.throw("Configure Pesapal credentials in DD Payment Settings")
        notification = settings.get(environment + "_ipn_id")
        base = "https://cybqa.pesapal.com/pesapalv3/api" if environment == "sandbox" else "https://pay.pesapal.com/v3/api"
        return environment, origin, key, secret, notification, base
    
    def ddprovider(path, body=None, params=None):
        config = ddconfig()
        key = config[2]
        secret = config[3]
        base = config[5]
        token_result = frappe.make_post_request(base + "/Auth/RequestToken", data=json.dumps({"consumer_key": key, "consumer_secret": secret}), headers={"Content-Type": "application/json", "Accept": "application/json"})
        if str(token_result.get("status")) != "200" or not token_result.get("token"):
            frappe.throw("Pesapal authentication failed")
        headers = {"Authorization": "Bearer " + token_result["token"], "Content-Type": "application/json", "Accept": "application/json"}
        if body is not None:
            result = frappe.make_post_request(base + path, data=json.dumps(body), headers=headers)
        else:
            result = frappe.make_get_request(base + path, params=params, headers=headers)
        if str(result.get("status")) != "200":
            frappe.throw("Pesapal could not complete this action")
        return result
    
    def csrf():
        staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
        account = frappe.session.user if staff else ddcustomer()
        doctype = "User" if staff else "DD Customer Account"
        token = frappe.utils.generate_hash(length=48)
        frappe.db.set_value(doctype, account, {"portal_csrf_hash": frappe.utils.sha256_hash(token), "portal_csrf_expires": frappe.utils.add_to_date(now_datetime(), minutes=10)})
        frappe.db.commit()
        return {"csrf_token": frappe.session.csrf_token or "", "mutation_token": token}
    
    def mutation_proof():
        staff = "System Manager" in roles() or "Field Operations Coordinator" in roles()
        account = frappe.get_doc("User", frappe.session.user) if staff else frappe.get_doc("DD Customer Account", ddcustomer())
        token = frappe.form_dict.get("portal_csrf_token")
        if not isinstance(token, str) or len(token) != 48 or frappe.utils.sha256_hash(token) != account.portal_csrf_hash or not account.portal_csrf_expires or frappe.utils.get_datetime(account.portal_csrf_expires) < now_datetime():
            frappe.throw("Refresh your account session before making changes", frappe.PermissionError)
    
    def register_ipn():
        if "System Manager" not in roles():
            frappe.throw("Not permitted", frappe.PermissionError)
        url = "https://thenetwork.frappe.cloud/api/method/dd_payment_ipn"
        result = ddprovider("/URLSetup/RegisterIPN", {"url": url, "ipn_notification_type": "GET"})
        if not result.get("ipn_id"):
            frappe.throw("Pesapal did not return a notification ID")
        environment = ddconfig()[0]
        frappe.db.set_value("DD Payment Settings", "DD Payment Settings", environment + "_ipn_id", result["ipn_id"])
        return {"success": True, "ipn_id": result["ipn_id"], "url": url}
    
    def ddlock(doctype, name):
        frappe.db.sql(f'SELECT name FROM `tab{doctype}` WHERE name=%s FOR UPDATE', (name,))
    
    def ddcustomer():
        user = frappe.session.user
        if user == 'Guest' or not frappe.db.get_value('User', user, 'enabled'):
            frappe.throw('Please sign in', frappe.PermissionError)
        account = frappe.db.get_value('DD Customer Account', {'user': user, 'email_verified': 1}, 'name')
        if not account or 'DD Customer' not in roles(user):
            frappe.throw('Verified customer account required', frappe.PermissionError)
        return account
    
    def ddowned(reference):
        account = ddcustomer()
        if not frappe.db.exists('Diaspora Request', {'name': reference, 'dd_customer_account': account}):
            frappe.throw('Request not found', frappe.PermissionError)
        return frappe.get_doc('Diaspora Request', reference)
    
    def validate_quote(doc, method=None):
        previous = doc.get_doc_before_save()
        if previous and previous.status != 'Draft':
            frappe.throw('Issued quotations are locked; prepare a new quotation for changed scope')
        if doc.status not in ('Draft', 'Issued'):
            frappe.throw('Quotation status is managed by the payment service')
        if doc.get('accepted_by') or doc.get('accepted_at'):
            frappe.throw('Acceptance is recorded only through customer approval')
        request = frappe.get_doc('Diaspora Request', doc.request)
        request.check_permission('read')
        ddlock('Diaspora Request', request.name)
        if doc.status == 'Issued' and frappe.db.exists('DD Quotation', {'request': doc.request, 'status': ['in', ['Issued', 'Accepted']], 'name': ['!=', doc.name or '']}):
            frappe.throw('A current quotation already exists; withdraw the unpaid quote before issuing a replacement')
        sequence_value_1 = (request.full_name, request.email)
        doc.customer_name = sequence_value_1[0]
        doc.customer_email = sequence_value_1[1]
        if doc.currency not in ('KES', 'USD', 'GBP', 'EUR'):
            frappe.throw('Unsupported quotation currency')
        if not doc.items or getdate(doc.valid_until) < getdate(doc.quotation_date):
            frappe.throw('Add projects and a valid quotation expiry')
        sequence_value_2 = (set(), money(0))
        seen = sequence_value_2[0]
        total = sequence_value_2[1]
        for item in doc.items:
            field = frappe.get_doc('Field Request', item.field_request)
            if field.diaspora_request != doc.request or field.name in seen:
                frappe.throw('Include each quoted project once, from this request')
            seen.add(field.name)
            count = item.get('planned_scouts')
            if isinstance(count, bool) or not count or float(count) != int(count) or (not 1 <= int(count) <= 20):
                frappe.throw('Enter a planned scout count from 1 to 20 for every project')
            if float(item.quantity) <= 0:
                frappe.throw('Quantity must be positive')
            item.project_title = field.project_title or field.request_type
            item.description = item.description or field.field_brief
            if not item.description:
                frappe.throw('Describe the agreed scope for every project')
            item.amount = float(money(money(item.rate) * money(item.quantity)))
            total += money(item.amount)
        if doc.status == 'Issued' and (not doc.terms):
            frappe.throw('Add the terms before issuing this quotation')
        sequence_value_3 = instalments(total)
        deposit = sequence_value_3[0]
        balance = sequence_value_3[1]
        sequence_value_4 = (float(total), float(deposit), float(balance))
        doc.total = sequence_value_4[0]
        doc.deposit_amount = sequence_value_4[1]
        doc.balance_amount = sequence_value_4[2]
        doc.deposit_percent = 50
        doc.version = 1
    
    def ddquote(reference):
        name = frappe.db.get_value('DD Quotation', {'request': reference, 'status': ['in', ['Issued', 'Accepted']]}, 'name', order_by='creation desc')
        return frappe.get_doc('DD Quotation', name) if name else None
    
    def ddobligations(quote):
        return frappe.get_all('DD Payment', filters={'quotation': quote.name}, fields=['name', 'kind', 'amount', 'currency', 'status'], order_by='creation asc')
    
    def ddbilling(request):
        quote = ddquote(request.name)
        if not quote:
            return {'quote': None, 'payments': [], 'documents': []}
        projects = []
        for item in quote.items:
            scouts = frappe.get_all('Field Task', filters={'field_request': item.field_request, 'status': ['!=', 'Cancelled']}, pluck='scout_profile')
            projects.append({'project': item.field_request, 'title': item.project_title, 'scope': item.description, 'planned_scouts': item.get('planned_scouts'), 'assigned_scouts': len(set(scouts)), 'amount': float(item.amount)})
        payments = ddobligations(quote)
        deposit_paid = any((p.kind == 'deposit' and p.status == 'Paid' for p in payments))
        for payment in payments:
            payment.amount = float(payment.amount)
            payment.can_pay = quote.status == 'Accepted' and payment.status != 'Paid' and (payment.kind == 'deposit' or (deposit_paid and request.status == 'Completed'))
        return {'quote': {'name': quote.name, 'version': quote.get('version') or 1, 'status': quote.status, 'currency': quote.currency, 'total': float(quote.total), 'deposit_amount': quote.get('deposit_amount'), 'balance_amount': quote.get('balance_amount'), 'valid_until': quote.valid_until, 'terms': quote.terms, 'scope': '\n'.join((item.description for item in quote.items)), 'projects': projects, 'can_accept': quote.status == 'Issued' and bool(quote.get('deposit_amount')) and (getdate(quote.valid_until) >= getdate())}, 'payments': payments, 'documents': []}
    
    def billing(reference=None):
        if reference:
            return {'billing': ddbilling(ddowned(reference))}
        account = ddcustomer()
        requests_ = frappe.get_all('Diaspora Request', filters={'dd_customer_account': account}, fields=['name', 'summary'], limit_page_length=200)
        return {'requests': [{'name': row.name, 'title': row.summary, 'billing': ddbilling(frappe.get_doc('Diaspora Request', row.name))} for row in requests_]}
    
    def accept_quote(reference, quote, version, submission_id):
        request = ddowned(reference)
        ddlock('Diaspora Request', request.name)
        current = ddquote(reference)
        if not current or current.name != quote or str(current.get('version') or 1) != str(version):
            frappe.throw('This quotation has changed')
        if current.status == 'Accepted':
            return {'success': True}
        if getdate(current.valid_until) < getdate() or not current.get('deposit_amount'):
            frappe.throw('This quotation needs to be reissued before acceptance')
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw('Invalid acceptance reference')
        frappe.db.set_value('DD Quotation', current.name, {'status': 'Accepted', 'accepted_by': frappe.session.user, 'accepted_at': now_datetime(), 'acceptance_reference': submission_id})
        for sequence_item_1 in zip(('deposit', 'balance'), instalments(current.total)):
            kind = sequence_item_1[0]
            amount = sequence_item_1[1]
            frappe.get_doc({'doctype': 'DD Payment', 'request': reference, 'quotation': current.name, 'kind': kind, 'amount': float(amount), 'currency': current.currency, 'status': 'Unpaid'}).insert(ignore_permissions=True)
        return {'success': True}
    
    def checkout(reference, payment, submission_id, return_origin=None):
        request = ddowned(reference)
        ddlock('Diaspora Request', request.name)
        obligation = frappe.get_doc('DD Payment', payment)
        quote = ddquote(reference)
        if not quote or quote.status != 'Accepted' or obligation.request != reference or (obligation.quotation != quote.name):
            frappe.throw('Payment does not belong to the accepted quotation', frappe.PermissionError)
        if obligation.status == 'Paid':
            frappe.throw('This payment is already complete')
        if obligation.kind == 'balance' and (request.status != 'Completed' or not frappe.db.exists('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'})):
            frappe.throw('The balance is payable after completion and verified deposit')
        sequence_value_1 = ddconfig()
        environment = sequence_value_1[0]
        origin = sequence_value_1[1]
        dd = sequence_value_1[2]
        dd = sequence_value_1[3]
        notification = sequence_value_1[4]
        dd = sequence_value_1[5]
        if return_origin and return_origin != origin:
            if environment != 'sandbox' or return_origin not in ('http://localhost:3000', 'http://127.0.0.1:3000') or (not frappe.db.get_single_value('DD Payment Settings', 'allow_local_return')):
                frappe.throw('Checkout return origin is not authorised')
            origin = return_origin
        if obligation.currency not in ([value.strip() for value in (frappe.db.get_single_value('DD Payment Settings', 'enabled_currencies') or 'KES').split(',')] or ['KES']):
            frappe.throw('This currency has not been enabled for checkout')
        if not notification:
            frappe.throw('Register the Pesapal notification endpoint first')
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw('Invalid checkout reference')
        active = frappe.db.get_value('DD Payment Attempt', {'payment': payment, 'status': ['in', ['Creating', 'Pending', 'Review']]}, 'name')
        if active:
            attempt = frappe.get_doc('DD Payment Attempt', active)
            if attempt.environment != environment or not attempt.checkout_url:
                frappe.throw('An earlier checkout is being reconciled. Please contact support before retrying')
            return {'checkout_url': checkout_url(attempt.checkout_url, environment)}
        merchant_reference = 'DD-' + frappe.utils.generate_hash(length=32)
        attempt = frappe.get_doc({'doctype': 'DD Payment Attempt', 'payment': payment, 'merchant_reference': merchant_reference, 'environment': environment, 'amount': obligation.amount, 'currency': obligation.currency, 'status': 'Creating', 'submission_id': submission_id}).insert(ignore_permissions=True)
        frappe.db.commit()
        try:
            result = ddprovider('/Transactions/SubmitOrderRequest', {'id': merchant_reference, 'currency': obligation.currency, 'amount': float(obligation.amount), 'description': f'Diaspora Desk {obligation.kind}', 'notification_id': notification, 'callback_url': origin + '/dashboard/billing?' + urlencode({'payment_return': '1', 'request': reference}), 'billing_address': {'email_address': frappe.session.user}})
            if result.get('merchant_reference') != merchant_reference or not result.get('order_tracking_id'):
                raise ValueError('Unexpected provider order')
            url = checkout_url(result.get('redirect_url'), environment)
            ddlock('DD Payment Attempt', attempt.name)
            attempt.reload()
            if attempt.tracking_id and attempt.tracking_id != result['order_tracking_id']:
                raise ValueError('Provider tracking conflict')
            frappe.db.set_value('DD Payment Attempt', attempt.name, {'tracking_id': result['order_tracking_id'], 'checkout_url': url, 'status': attempt.status if attempt.status in ('Paid', 'Reversed', 'Failed') else 'Pending'})
            return {'checkout_url': url}
        except Exception:
            ddlock('DD Payment Attempt', attempt.name)
            attempt.reload()
            if attempt.status not in ('Paid', 'Reversed'):
                frappe.db.set_value('DD Payment Attempt', attempt.name, 'status', 'Review')
            frappe.db.commit()
            frappe.throw('Checkout needs reconciliation. Please contact support before retrying')
    
    def ddverify(attempt_name, tracking_id=None):
        attempt = frappe.get_doc('DD Payment Attempt', attempt_name)
        tracking_id = tracking_id or attempt.tracking_id
        if not tracking_id:
            return
        if attempt.environment != ddconfig()[0]:
            frappe.throw('Configure the original payment environment to reconcile this attempt')
        data = ddprovider('/Transactions/GetTransactionStatus', params={'orderTrackingId': tracking_id})
        state = verified_status(data, attempt.merchant_reference, attempt.amount, attempt.currency)
        payment = frappe.get_doc('DD Payment', attempt.payment)
        ddlock('Diaspora Request', payment.request)
        ddlock('DD Payment', payment.name)
        attempt.reload()
        payment.reload()
        if attempt.status == 'Paid' and state in ('Pending', 'Failed'):
            return
        frappe.db.set_value('DD Payment Attempt', attempt.name, {'tracking_id': tracking_id, 'status': state, 'confirmation_code': data.get('confirmation_code'), 'verified_at': now_datetime()})
        if state == 'Paid':
            if payment.status == 'Paid' and payment.get('paid_attempt') != attempt.name:
                frappe.db.set_value('DD Payment Attempt', attempt.name, 'status', 'Review')
                return
            frappe.db.set_value('DD Payment', payment.name, {'status': 'Paid', 'paid_attempt': attempt.name, 'paid_at': now_datetime()})
        elif state == 'Reversed' and payment.get('paid_attempt') == attempt.name:
            frappe.db.set_value('DD Payment', payment.name, 'status', 'Reversed')
    
    def ipn(OrderTrackingId=None, OrderMerchantReference=None, OrderNotificationType=None):
        if not isinstance(OrderTrackingId, str) or len(OrderTrackingId) > 100 or (not isinstance(OrderMerchantReference, str)) or (len(OrderMerchantReference) > 50):
            frappe.throw('Invalid notification')
        name = frappe.db.get_value('DD Payment Attempt', {'merchant_reference': OrderMerchantReference}, 'name')
        if not name:
            frappe.throw('Unknown payment')
        attempt = frappe.get_doc('DD Payment Attempt', name)
        if attempt.tracking_id and attempt.tracking_id != OrderTrackingId:
            frappe.throw('Payment reference mismatch')
        try:
            ddverify(name, OrderTrackingId)
            frappe.db.commit()
        except Exception:
            frappe.db.rollback()
            frappe.response.update({'orderNotificationType': 'IPNCHANGE', 'orderTrackingId': OrderTrackingId, 'orderMerchantReference': OrderMerchantReference, 'status': 500})
            return
        frappe.response.update({'orderNotificationType': 'IPNCHANGE', 'orderTrackingId': OrderTrackingId, 'orderMerchantReference': OrderMerchantReference, 'status': 200})
    
    def refresh(reference):
        ddowned(reference)
        attempts = frappe.db.sql("SELECT a.name FROM `tabDD Payment Attempt` a\n        INNER JOIN `tabDD Payment` p ON a.payment=p.name\n        WHERE p.request=%s AND a.tracking_id IS NOT NULL AND a.status IN ('Pending','Review') LIMIT 10", (reference,), as_dict=True)
        for attempt in attempts:
            ddverify(attempt.name)
        return {'success': True}
    
    def reconcile():
        for row in frappe.get_all('DD Payment Attempt', filters={'status': ['in', ['Pending', 'Review']], 'tracking_id': ['is', 'set']}, pluck='name', limit_page_length=100, order_by='modified asc'):
            try:
                ddverify(row)
                frappe.db.commit()
            except Exception:
                frappe.db.rollback()
                frappe.log_error(title='Pesapal reconciliation failed', message=f'Review payment attempt {row}; provider verification did not complete.')
    
    def require_deposit(doc, method=None):
        if not doc.field_request:
            return
        previous = doc.get_doc_before_save()
        entering = doc.is_new() or (previous and (previous.scout_profile != doc.scout_profile or previous.field_request != doc.field_request or (previous.status == 'Cancelled' and doc.status != 'Cancelled')))
        if not entering or doc.status == 'Cancelled':
            return
        reference = frappe.db.get_value('Field Request', doc.field_request, 'diaspora_request')
        if not reference:
            return
        ddlock('Diaspora Request', reference)
        quote = ddquote(reference)
        if not quote or quote.status != 'Accepted' or (not frappe.db.exists('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'})):
            frappe.throw('Accept the quotation and verify the 50% deposit before assigning scouts')
        paid_attempt = frappe.db.get_value('DD Payment', {'quotation': quote.name, 'kind': 'deposit', 'status': 'Paid'}, 'paid_attempt')
        environment = frappe.db.get_value('DD Payment Attempt', paid_attempt, 'environment') if paid_attempt else None
        if environment != 'live' and (not (environment == 'sandbox' and frappe.db.get_single_value('DD Payment Settings', 'allow_sandbox_dispatch') and frappe.db.get_value('Diaspora Request', reference, 'sandbox_testing'))):
            frappe.throw('A live verified deposit is required for dispatch; sandbox dispatch must be explicitly enabled on a test site')
        line = None
        for row in quote.items:
            if row.field_request == doc.field_request:
                line = row
                break
        if not line:
            frappe.throw('This project is not included in the paid quotation')
        scouts = set(frappe.get_all('Field Task', filters={'field_request': doc.field_request, 'name': ['!=', doc.name or ''], 'status': ['!=', 'Cancelled']}, pluck='scout_profile'))
        scouts.add(doc.scout_profile)
        if len(scouts) > int(line.planned_scouts):
            frappe.throw('Scout count exceeds the accepted quotation; review the agreed scope first')
    
    def withdraw_quote(quote):
        document = frappe.get_doc('DD Quotation', quote)
        document.check_permission('write')
        ddlock('Diaspora Request', document.request)
        document.reload()
        if document.status != 'Issued' or frappe.db.exists('DD Payment', {'quotation': document.name}):
            frappe.throw('Only an unaccepted quotation can be withdrawn; accepted work needs a reviewed amendment')
        frappe.db.set_value('DD Quotation', document.name, 'status', 'Withdrawn')
        return {'success': True}

    def disputes(reference=None):
        account = ddcustomer()
        filters = {"customer_account": account}
        if reference:
            ddowned(reference)
            filters["request"] = reference
        rows = frappe.get_all("DD Dispute", filters=filters, fields=["name", "request", "subject", "reason", "status", "modified", "response"], order_by="modified desc", limit_page_length=200)
        return {"disputes": rows}

    def create_dispute(reference, subject, reason, submission_id):
        request = ddowned(reference)
        ddlock("Diaspora Request", request.name)
        if not isinstance(subject, str) or not 1 <= len(subject.strip()) <= 140 or not isinstance(reason, str) or not 20 <= len(reason.strip()) <= 4000:
            frappe.throw("Describe the issue with a subject and 20 to 4000 characters")
        if not isinstance(submission_id, str) or not 1 <= len(submission_id) <= 100:
            frappe.throw("Invalid dispute reference")
        existing = frappe.db.get_value("DD Dispute", {"request": reference, "submission_id": submission_id}, "name")
        if existing:
            return {"success": True, "dispute": {"name": existing}}
        document = frappe.get_doc({"doctype": "DD Dispute", "request": reference, "customer_account": ddcustomer(),
            "subject": subject.strip(), "reason": reason.strip(), "submission_id": submission_id, "status": "Open"})
        document.insert(ignore_permissions=True)
        return {"success": True, "dispute": {"name": document.name}}

    def validate_dispute(doc):
        request = frappe.get_doc("Diaspora Request", doc.request)
        if request.dd_customer_account != doc.customer_account:
            frappe.throw("Dispute ownership does not match the request")
        previous = doc.get_doc_before_save()
        if not previous:
