def project_plan(source):
    try:
        details = json.loads(source.get("project_details") or "[]")
    except (TypeError, ValueError):
        frappe.throw("Project details must be a JSON array.")
    if not isinstance(details, list):
        frappe.throw("Project details must be a JSON array.")
    strict = source.get("project_contract_version") == 1
    if strict and not source.get("project_details"):
        frappe.throw("Missing structured projects. Review the assessment.")
    if not details and not source.get("project_details") and source.category != "out_of_scope":
        seen = []
        for row in source.get("evidence_checklist") or []:
            prefix = (row.evidence_item or "").split("[", 1)[0].strip().split()
            number = row.get("project_number") or (int(prefix[1]) if len(prefix) == 2 and prefix[1].isdigit() else 0)
            if number and number not in seen:
                seen.append(number)
                details.append({"number": number, "description": (row.evidence_item or "").split(":", 1)[0], "county": row.get("county") or "", "eligibility": "supported"})
    projects = []
    ids = []
    numbers = []
    for detail in details:
        if not isinstance(detail, dict):
            frappe.throw("Every project must be an object.")
        number = detail.get("number")
        identity = detail.get("id") or ("legacy-project-" + str(number) if not strict else "")
        if not isinstance(number, int) or isinstance(number, bool) or number < 1 or number in numbers:
            frappe.throw("Project numbers must be unique positive integers.")
        if not isinstance(identity, str) or not identity.strip() or len(identity) > 80 or identity in ids:
            frappe.throw("Project IDs must be valid and unique.")
        ids.append(identity)
        numbers.append(number)
        eligibility = detail.get("eligibility") or ("supported" if not strict else "")
        if eligibility not in ["supported", "scope_confirmation", "unsupported", "overseas"]:
            frappe.throw("Invalid project eligibility.")
        if eligibility in ["unsupported", "overseas"]:
            continue
        scope = detail.get("scope") or detail.get("description")
        if not isinstance(scope, str) or not scope.strip():
            frappe.throw("Every eligible project needs its own scope.")
        evidence = detail.get("evidence_tasks")
        if evidence is None and not strict:
            evidence = []
            for row in source.get("evidence_checklist") or []:
                prefix = (row.evidence_item or "").split("[", 1)[0].split(":", 1)[0].strip().split()
                row_number = row.get("project_number") or (int(prefix[1]) if len(prefix) == 2 and prefix[1].isdigit() else 0)
                if row_number == number or len(details) == 1:
                    evidence.append((row.evidence_item or "").split(":", 1)[-1].strip())
        if not isinstance(evidence, list):
            frappe.throw("Each project needs structured evidence tasks.")
        for task in evidence:
            if not isinstance(task, str) or not task.strip():
                frappe.throw("Invalid project evidence task.")
        sites = []
        for site in source.get("customer_sites") or []:
            if site.get("project_ids"):
                try:
                    members = json.loads(site.project_ids)
                except (TypeError, ValueError):
                    frappe.throw("Invalid site project IDs.")
                if not isinstance(members, list):
                    frappe.throw("Site project IDs must be an array.")
                if identity in members:
                    sites.append(site)
            elif strict:
                frappe.throw("A submitted location is missing its project IDs.")
            else:
                label = (site.site_label or "").split(":", 1)[0].replace("Projects ", "").replace("Project ", "").split("/", 1)[0]
                if str(number) in [part.strip() for part in label.split("&")]:
                    sites.append(site)
        counties = []
        for site in sites:
            if site.county and site.county not in counties:
                counties.append(site.county)
        county = ", ".join(counties) or detail.get("county") or ""
        title = detail.get("description") or scope
        categories = {"land_property_check": "Property Verification", "construction_progress": "Construction Progress", "business_asset_check": "Business / Merchant Verification", "custom_ground_verification": "General Site Visit"}
        category = detail.get("service_category")
        if strict and category not in categories:
            frappe.throw("Each project needs a valid service category.")
        request_type = categories.get(category) or categories.get(source.category, "General Site Visit")
        if not category:
            text = title.lower()
            if any(word in text for word in ["shop", "business", "salon", "merchant"]):
                request_type = "Business / Merchant Verification"
            elif "construction" in text:
                request_type = "Construction Progress"
            elif any(word in text for word in ["land", "property", "plot"]):
                request_type = "Property Verification"
        if strict and source.get("dd_customer_account") and eligibility == "supported" and not sites:
            frappe.throw("A supported project is missing its submitted location.")
        projects.append({"id": identity, "number": number, "title": title, "scope": scope, "county": county, "evidence": evidence, "sites": sites, "request_type": request_type, "review": 1 if not county or not evidence or eligibility == "scope_confirmation" else 0})
    if strict:
        for site in source.get("customer_sites") or []:
            members = json.loads(site.get("project_ids") or "[]")
            seen_members = []
            for member in members:
                if member in seen_members:
                    frappe.throw("Duplicate site project ID.")
                seen_members.append(member)
                valid = False
                for project in projects:
                    if member == project["id"]:
                        valid = True
                if not valid:
                    frappe.throw("A location references an unknown project.")
            if not members:
                frappe.throw("A location must identify its project.")
