if doc.field_request:
    request = frappe.get_doc("Field Request", doc.field_request)
    tasks = frappe.get_all("Field Task", filters={"field_request": request.name, "status": ["!=", "Cancelled"]}, fields=["status"])
    if tasks and request.status != "Cancelled":
        status = "Assigned"
        if all(task.status == "Approved" for task in tasks):
            status = "Completed"
        elif any(task.status in ["In Progress", "Submitted", "Approved"] for task in tasks):
            status = "In Progress"
        frappe.db.set_value("Field Request", request.name, "status", status)
        if request.diaspora_request:
            source = frappe.get_doc("Diaspora Request", request.diaspora_request)
            expected = []
            for project in project_plan(source)["projects"]:
                expected.append(project["number"])
            rows = frappe.get_all("Field Request", filters={"diaspora_request": source.name, "status": ["!=", "Cancelled"]}, fields=["project_number", "status"])
            overall = "Assigned"
            completed = []
            for row in rows:
                if row.status == "Completed":
                    completed.append(row.project_number)
            missing = False
            for number in expected:
                if number not in completed:
                    missing = True
            if expected and not missing:
                overall = "Completed"
            elif any(row.status in ["In Progress", "Completed"] for row in rows):
                overall = "In Progress"
            if source.status != "Rejected":
                frappe.db.set_value("Diaspora Request", source.name, "status", overall)
